      return GoogleSignInResult(newUser: isNew, uid: uid, displayName: displayName);
    } catch (e) {
      rethrow;
    }
  }

  /// Finalize signup for new users (social or phone). Creates /users/{uid} document with chosen role.
  /// Admin accounts are created active (no approval required).
  static Future<bool> completeSignup({required String uid, required String displayName, required String role, String? email, String? phone, String provider = 'unknown'}) async {
    try {
      // Immediately activate all roles (admin included)
      final status = 'active';
      final docData = {
        'displayName': displayName,
        'email': email,
        'phone': phone,
        'role': role,
        'status': status,
        'provider': provider,
        'createdAt': FieldValue.serverTimestamp(),
      };
      await _firestore.collection('users').doc(uid).set(docData, SetOptions(merge: true));
      // update Firebase user displayName if possible
      final user = _auth.currentUser;
      if (user != null && (user.displayName == null || user.displayName!.isEmpty)) {
        await user.updateDisplayName(displayName);
      }
      return true;
    } catch (e) {
      return false;
    }
  }

  static Future<void> signOut() async {
    try {
      await _auth.signOut();
      await _googleSignIn.signOut();
    } catch (_) {}
  }
}

