import 'dart:async';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:google_sign_in/google_sign_in.dart';

// ---------- Helper Models ----------

class CheckResult {
  final bool exists;
  final List<String> providers;
  final String status;
  CheckResult({
    required this.exists,
    this.providers = const <String>[],
    this.status = 'none',
  });
}

class GoogleSignInResult {
  final bool newUser;
  final String? uid;
  final String? displayName;
  GoogleSignInResult({required this.newUser, this.uid, this.displayName});
}

class VerifyResult {
  final bool success;
  final bool newUser;
  final String? uid;
  VerifyResult({required this.success, required this.newUser, this.uid});
}

// ---------- Auth Service ----------

class AuthService {
  static final FirebaseAuth _auth = FirebaseAuth.instance;
  static final FirebaseFirestore _firestore = FirebaseFirestore.instance;
  static final GoogleSignIn _googleSignIn = GoogleSignIn();

  // ------------------ Get User Role ------------------
  static Future<String?> getUserRole(String uid) async {
    try {
      final doc = await _firestore.collection('users').doc(uid).get();
      if (doc.exists) {
        final data = doc.data();
        return data?['role'] as String?;
      }
    } catch (e) {
      print('getUserRole error: $e');
    }
    return null;
  }

  // ------------------ Identifier Check ------------------
  static Future<CheckResult> checkIdentifier({
    required String method,
    required String identifier,
  }) async {
    try {
      if (method == 'email') {
        // 1️⃣ Check Firestore first
        final q = await _firestore
            .collection('users')
            .where('email', isEqualTo: identifier)
            .limit(1)
            .get();

        if (q.docs.isNotEmpty) {
          final data = q.docs.first.data();
          final provider = (data['provider'] ?? 'password') as String;
          final status = data['status'] ?? 'active';
          return CheckResult(
            exists: true,
            providers: [provider],
            status: status,
          );
        }

        // 2️⃣ Try Firebase Auth
        try {
          await _auth.signInWithEmailAndPassword(
              email: identifier, password: 'invalid-temp-password');
        } on FirebaseAuthException catch (e) {
          if (e.code == 'wrong-password' ||
              e.code == 'user-disabled' ||
              e.code == 'too-many-requests') {
            return CheckResult(exists: true, providers: ['password'], status: 'active');
          } else if (e.code == 'user-not-found') {
            return CheckResult(exists: false);
          }
        }

        return CheckResult(exists: false);
      } else if (method == 'phone') {
        final q = await _firestore
            .collection('users')
            .where('phone', isEqualTo: identifier)
            .limit(1)
            .get();
        if (q.docs.isNotEmpty) {
          final data = q.docs.first.data();
          return CheckResult(
            exists: true,
            providers: [data['provider'] ?? 'phone'],
            status: data['status'] ?? 'active',
          );
        }
        return CheckResult(exists: false);
      }

      return CheckResult(exists: false);
    } catch (e) {
      print('checkIdentifier error: $e');
      return CheckResult(exists: false);
    }
  }

  // ------------------ Email Sign-In / Sign-Up ------------------

  static Future<Map<String, dynamic>> signInWithEmail({
