        'status': 'active',
        'provider': 'password',
        'createdAt': FieldValue.serverTimestamp(),
      });

      return {'success': true, 'uid': uid, 'role': role};
    } catch (e) {
      return {'success': false, 'error': e.toString()};
    }
  }

  // ------------------ Phone Authentication ------------------

  static Future<Map<String, dynamic>> sendPhoneVerification({
    required String phone,
  }) async {
    final q = await _firestore
        .collection('users')
        .where('phone', isEqualTo: phone)
        .limit(1)
        .get();
    final isNew = q.docs.isEmpty;
    final completer = Completer<Map<String, dynamic>>();

    await _auth.verifyPhoneNumber(
      phoneNumber: phone,
      timeout: const Duration(seconds: 60),
      verificationCompleted: (cred) async {
        try {
          final userCred = await _auth.signInWithCredential(cred);
          final uid = userCred.user?.uid;
          completer.complete({
            'verificationId': '',
            'auto': true,
            'uid': uid,
            'newUser': isNew,
          });
        } catch (e) {
          completer.completeError(e);
        }
      },
      verificationFailed: (e) {
        completer.completeError(e);
      },
      codeSent: (id, token) {
        completer.complete({
          'verificationId': id,
          'auto': false,
          'newUser': isNew,
        });
      },
      codeAutoRetrievalTimeout: (_) {},
    );

    return completer.future;
  }

  // ✅ Added / Fixed verifyPhoneOtp definition
  static Future<VerifyResult> verifyPhoneOtp({
    required String verificationId,
    required String smsCode,
  }) async {
    try {
      final cred = PhoneAuthProvider.credential(
          verificationId: verificationId, smsCode: smsCode);
      final userCred = await _auth.signInWithCredential(cred);
      final uid = userCred.user?.uid;
      final newUser = userCred.additionalUserInfo?.isNewUser ?? false;
      return VerifyResult(success: true, newUser: newUser, uid: uid);
    } catch (e) {
      print('verifyPhoneOtp error: $e');
      return VerifyResult(success: false, newUser: false, uid: null);
    }
  }

  // ------------------ Google Sign-In ------------------

  static Future<GoogleSignInResult> signInWithGoogle() async {
    try {
      final googleUser = await _googleSignIn.signIn();
      if (googleUser == null) return GoogleSignInResult(newUser: false);

      final googleAuth = await googleUser.authentication;
      final cred = GoogleAuthProvider.credential(
        idToken: googleAuth.idToken,
        accessToken: googleAuth.accessToken,
      );

      final userCred = await _auth.signInWithCredential(cred);
      final uid = userCred.user?.uid;
      final newUser = userCred.additionalUserInfo?.isNewUser ?? false;
      final name = userCred.user?.displayName;

      return GoogleSignInResult(newUser: newUser, uid: uid, displayName: name);
    } catch (e) {
      print('Google SignIn error: $e');
      return GoogleSignInResult(newUser: false);
    }
  }

  // ------------------ Complete Signup ------------------

  static Future<bool> completeSignup({
    required String uid,
    required String displayName,
    required String role,
    String? email,
    String? phone,
    String provider = 'unknown',
  }) async {
    try {
      await _firestore.collection('users').doc(uid).set({
        'displayName': displayName,
        'email': email,
        'phone': phone,
        'role': role,
        'status': 'active',
        'provider': provider,
        'createdAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      final user = _auth.currentUser;
      if (user != null &&
          (user.displayName == null || user.displayName!.isEmpty)) {
        await user.updateDisplayName(displayName);
      }

      return true;
    } catch (e) {
      print('completeSignup error: $e');
      return false;
    }
  }

  // ------------------ Sign out ------------------

  static Future<void> signOut() async {
    try {
      await _googleSignIn.signOut();
      await _auth.signOut();
    } catch (_) {}
  }
}

